"use client"

import * as React from "react"

import { Button } from "@/components/standard/button"
import { FilterSelect } from "@/components/standard/filter-select"
import { RefreshButton } from "@/components/standard/refresh-button"
import { Search } from "@/components/standard/search"

export type StandardListFilterOption = {
  id: string
  label: string
  value: string
}

export type StandardListFilter = {
  key: string
  label: string
  type: "badge" | "select"
  columnKey: string
  options: StandardListFilterOption[]
}

export type StandardListTitleBar = {
  left?: string
  center?: string
  actions?: { id: string; label: string }[]
}

export function readingListCell(item: object, key: string) {
  const record = item as Record<string, unknown>
  const value = record[key]
  if (value === null || value === undefined) {
    return ""
  }
  return String(value)
}

export function filteringListRows<T extends object>(
  rows: T[],
  query: string,
  filters: StandardListFilter[],
  selected: Record<string, string>
) {
  const needle = query.trim().toLowerCase()

  return rows.filter((row) => {
    for (const filter of filters) {
      const picked = selected[filter.key]
      if (!picked) {
        continue
      }
      if (readingListCell(row, filter.columnKey) !== picked) {
        return false
      }
    }

    if (!needle) {
      return true
    }

    const haystack = Object.values(row as Record<string, unknown>)
      .map((value) => String(value ?? "").toLowerCase())
      .join(" ")

    return haystack.includes(needle)
  })
}

export function RendersStandardListChrome({
  titleBar,
  errorBar,
  showSearch,
  searchPlaceholder,
  searchValue,
  onSearchChange,
  showRefresh,
  onRefresh,
  filterBadge,
  filterSelect,
  filters,
  selectedFilters,
  onFilterChange,
}: {
  titleBar?: StandardListTitleBar
  errorBar?: string
  showSearch?: boolean
  searchPlaceholder?: string
  searchValue: string
  onSearchChange: (value: string) => void
  showRefresh?: boolean
  onRefresh?: () => void
  filterBadge?: boolean
  filterSelect?: boolean
  filters: StandardListFilter[]
  selectedFilters: Record<string, string>
  onFilterChange: (key: string, value: string) => void
}) {
  const badgeFilters = filters.filter((filter) => filter.type === "badge")
  const selectFilters = filters.filter((filter) => filter.type === "select")
  const showToolbar = Boolean(
    showSearch || showRefresh || filterSelect || filterBadge || titleBar
  )

  return (
    <div className="flex flex-col gap-2">
      {titleBar ? (
        <div className="flex items-center justify-between gap-2 border-b border-border pb-2">
          <span className="text-sm font-semibold">{titleBar.left}</span>
          {titleBar.center ? (
            <span className="text-xs text-muted-foreground">{titleBar.center}</span>
          ) : null}
          <div className="flex gap-1">
            {titleBar.actions?.map((action) => (
              <Button key={action.id} size="sm" tone="outline">
                {action.label}
              </Button>
            ))}
          </div>
        </div>
      ) : null}
      {errorBar ? (
        <p className="rounded-md border border-destructive/40 bg-destructive/10 px-2 py-1 text-xs text-destructive">
          {errorBar}
        </p>
      ) : null}
      {showToolbar ? (
        <div className="flex flex-wrap items-center gap-2">
          {showSearch ? (
            <div className="min-w-40 flex-1">
              <Search
                placeholder={searchPlaceholder ?? "Search"}
                value={searchValue}
                onChange={(event) => onSearchChange(event.target.value)}
              />
            </div>
          ) : null}
          {filterSelect
            ? selectFilters.map((filter) => (
                <FilterSelect
                  key={filter.key}
                  value={selectedFilters[filter.key] ?? ""}
                  onChange={(event) =>
                    onFilterChange(filter.key, event.target.value)
                  }
                >
                  <option value="">{filter.label}</option>
                  {filter.options.map((option) => (
                    <option key={option.id} value={option.value}>
                      {option.label}
                    </option>
                  ))}
                </FilterSelect>
              ))
            : null}
          {showRefresh ? <RefreshButton onClick={onRefresh} /> : null}
        </div>
      ) : null}
      {filterBadge ? (
        <div className="flex flex-wrap gap-2">
          {badgeFilters.map((filter) => (
            <div key={filter.key} className="flex flex-wrap gap-1">
              {filter.options.map((option) => {
                const isOn = selectedFilters[filter.key] === option.value

                return (
                  <Button
                    key={option.id}
                    size="sm"
                    tone={isOn ? "default" : "outline"}
                    onClick={() =>
                      onFilterChange(filter.key, isOn ? "" : option.value)
                    }
                  >
                    {option.label}
                  </Button>
                )
              })}
            </div>
          ))}
        </div>
      ) : null}
    </div>
  )
}

export function RendersStandardListPager({
  page,
  pageSize,
  total,
  onPageChange,
  onPageSizeChange,
}: {
  page: number
  pageSize: number
  total: number
  onPageChange: (page: number) => void
  onPageSizeChange: (pageSize: number) => void
}) {
  const pageCount = Math.max(1, Math.ceil(total / pageSize))
  const start = total === 0 ? 0 : (page - 1) * pageSize + 1
  const end = Math.min(total, page * pageSize)

  return (
    <div className="flex flex-wrap items-center justify-between gap-2 border-t border-border pt-2 text-xs text-muted-foreground">
      <span>
        Showing {start} to {end} of {total}
      </span>
      <div className="flex items-center gap-2">
        <FilterSelect
          value={String(pageSize)}
          onChange={(event) => onPageSizeChange(Number(event.target.value))}
        >
          <option value="3">3</option>
          <option value="5">5</option>
          <option value="10">10</option>
        </FilterSelect>
        <Button
          size="sm"
          tone="outline"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
        >
          Prev
        </Button>
        <Button
          size="sm"
          tone="outline"
          disabled={page >= pageCount}
          onClick={() => onPageChange(page + 1)}
        >
          Next
        </Button>
      </div>
    </div>
  )
}
